<?php
$zipData = base64_decode('');
file_put_contents('deploy_rose.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_rose.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_rose.zip');
    echo '<h1>Colors and Sidebar Accuracy Fixed!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>